  box-shadow: 0 0 10px rgba(145, 243, 168, 0.1);
  background: #000;
  display: flex;
  justify-content: center;
  align-items: center;
}

.pong-canvas {
  display: block;
  image-rendering: pixelated;
}

.pong-controls-hint {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  color: var(--ink-muted);
  text-align: center;
  margin: 0;
  letter-spacing: 0.05em;
}

.pong-touch-pad {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.5rem;
  width: 100%;
}

.pong-touch-btn {
  background: var(--ink);
  border: 1px solid var(--line);
  color: var(--cyan);
  font-family: var(--font-mono);
  font-size: 0.85rem;
  padding: 0.6rem 0;
  cursor: pointer;
  transition: all 0.15s;
}

.pong-touch-btn:hover, .pong-touch-btn:active {
  background: var(--cyan);
  color: var(--ink);
  border-color: var(--cyan);
}

