      ctx.setLineDash([]);

      // Player 1 Paddle (Cyan)
      ctx.fillStyle = '#91f3a8';
      ctx.shadowColor = '#91f3a8';
      ctx.shadowBlur = 8;
      ctx.fillRect(player1.x, player1.y, player1.width, player1.height);

      // Player 2 / AI Paddle (Green)
      ctx.fillStyle = '#20ef4f';
      ctx.shadowColor = '#20ef4f';
      ctx.fillRect(player2.x, player2.y, player2.width, player2.height);

      // Ball (Red)
      ctx.fillStyle = '#ff2244';
      ctx.shadowColor = '#ff2244';
      ctx.fillRect(ball.x, ball.y, ballSize, ballSize);
      ctx.shadowBlur = 0;

      if (gameOver) {
        ctx.fillStyle = "rgba(9, 11, 10, 0.85)";
        ctx.fillRect(0, 0, WIDTH, HEIGHT);
        let winText = "PLAYER 1 WINS";
        if (p2Score >= 5) {
          winText = gameMode === "vs_ai" ? "AI WINS // DEFEAT" : "PLAYER 2 WINS";
        }
        ctx.fillStyle = p1Score >= 5 ? "#20ef4f" : "#ff2244";
        ctx.font = "bold 18px monospace";
        ctx.textAlign = "center";
        ctx.fillText(winText, WIDTH / 2, HEIGHT / 2 - 10);
        ctx.fillStyle = "#91f3a8";
        ctx.font = "12px monospace";
        ctx.fillText("PRESS ENTER TO RESTART", WIDTH / 2, HEIGHT / 2 + 20);
      } else if (isPaused) {
        ctx.fillStyle = "rgba(9, 11, 10, 0.75)";
        ctx.fillRect(0, 0, WIDTH, HEIGHT);
        ctx.fillStyle = "#91f3a8";
        ctx.font = "bold 16px monospace";
        ctx.textAlign = "center";
        ctx.fillText("PAUSED", WIDTH / 2, HEIGHT / 2);
      }
    }

    function loop() {
      update();
      draw();
      requestAnimationFrame(loop);
    }

    const handleKeyDown = (e) => {
      if (!overlay.classList.contains("is-active")) return;
      // Player 1: W / S
      if (e.key === "w" || e.key === "W") {
        player1.dy = -6;
        e.preventDefault();
      } else if (e.key === "s" || e.key === "S") {
        player1.dy = 6;
        e.preventDefault();
      }

      // Player 2: Arrow Up / Arrow Down (only in 2p mode)
      if (gameMode === "2p") {
        if (e.key === "ArrowUp") {
          player2.dy = -6;
          e.preventDefault();
        } else if (e.key === "ArrowDown") {
          player2.dy = 6;
          e.preventDefault();
        }
      }

      if (e.key === " ") {
        isPaused = !isPaused;
        e.preventDefault();
      } else if (e.key === "Enter" && gameOver) {
        this.pongReset();
        e.preventDefault();
      }
    };

    const handleKeyUp = (e) => {
      if (e.key === "w" || e.key === "W" || e.key === "s" || e.key === "S") {
        player1.dy = 0;
      }
      if (gameMode === "2p") {
        if (e.key === "ArrowUp" || e.key === "ArrowDown") {
          player2.dy = 0;
        }
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    window.addEventListener("keyup", handleKeyUp);

    overlay.querySelectorAll(".pong-touch-btn").forEach(btn => {
      const act = btn.getAttribute("data-action");
      btn.addEventListener("mousedown", () => { player1.dy = act === "up" ? -6 : 6; });
      btn.addEventListener("mouseup", () => { player1.dy = 0; });
      btn.addEventListener("touchstart", (e) => { e.preventDefault(); player1.dy = act === "up" ? -6 : 6; });
      btn.addEventListener("touchend", () => { player1.dy = 0; });
    });

    this.pongReset();
    requestAnimationFrame(loop);
  }
});

