      entry.style.setProperty("--entry-index", index);
      if (item.url) {
        entry.href = item.url;
        entry.target = "_blank";
        entry.rel = "noopener noreferrer";
      }

      const tag = document.createElement("span");
      tag.className = "card-tag";
