      separator.setAttribute("aria-hidden", "true");
      separator.textContent = "/";
      const folderLink = document.createElement("a");
      folderLink.href = `#${Model.basePath}/experience/${folderId}`;
      folderLink.dataset.routeFolder = folderId;
