      return true;
    }
  },

  setSound(enabled) {
    try {
      localStorage.setItem("portfolio-sound", enabled ? "on" : "off");
    } catch {}
  },

  playSelect() {
    if (!this.soundEnabled()) return;
    this.els.audio.currentTime = 0;
    this.els.audio.play().catch(() => {});
  },
};

