          if (grid[r][c] === 0) continue outer;
        }
        const row = grid.splice(r, 1)[0].fill(0);
        grid.unshift(row);
        r++;
        rowCount++;
      }
      if (rowCount > 0) {
        lines += rowCount;
        score += rowCount * 100 * rowCount;
        scoreEl.textContent = `SCORE: ${score}`;
        linesEl.textContent = `LINES: ${lines}`;
        if (score > hi) {
          hi = score;
          hiEl.textContent = `HI: ${hi}`;
