        grid.unshift(row);
        r++;
        rowCount++;
      }
      if (rowCount > 0) {
        lines += rowCount;
        score += rowCount * 100 * rowCount;
        scoreEl.textContent = `SCORE: ${score}`;
        linesEl.textContent = `LINES: ${lines}`;
        if (score > hi) {
          hi = score;
          hiEl.textContent = `HI: ${hi}`;
          localStorage.setItem("cyber_tetris_hi", hi);
        }
