        const act = btn.getAttribute("data-action");
        if (act === "left") playerMove(-1);
        else if (act === "right") playerMove(1);
        else if (act === "rotate") playerRotate();
        else if (act === "drop") playerDrop();
      });
    });

    this.tetrisReset();
    requestAnimationFrame(update);
  }
});

