    const paddleHeight = 60;
    const ballSize = 8;

    let player1 = {
      x: 15,
      y: HEIGHT / 2 - paddleHeight / 2,
      width: paddleWidth,
      height: paddleHeight,
      dy: 0
    };

    let player2 = {
      x: WIDTH - 25,
      y: HEIGHT / 2 - paddleHeight / 2,
      width: paddleWidth,
      height: paddleHeight,
      dy: 0
    };

