      p2Score = 0;
      p1ScoreEl.textContent = `PLAYER 1: ${p1Score}`;
      p2ScoreEl.textContent = gameMode === "vs_ai" ? `AI: ${p2Score}` : `PLAYER 2: ${p2Score}`;
      resetBall();
      isPaused = false;
      gameOver = false;
    };

    this.pongPause = () => {
      isPaused = true;
    };

    function resetBall(servingToP1 = true) {
      ball.x = WIDTH / 2;
      ball.y = HEIGHT / 2;
      ball.speed = 5;
      const angle = (Math.random() * 0.6 - 0.3) * Math.PI;
      const dir = servingToP1 ? -1 : 1;
      ball.vx = dir * ball.speed * Math.cos(angle);
      ball.vy = ball.speed * Math.sin(angle);
    }

    function update() {
      if (!overlay.classList.contains("is-active") || isPaused || gameOver) return;

      player1.y += player1.dy;
      if (player1.y < 0) player1.y = 0;
      if (player1.y > HEIGHT - player1.height) player1.y = HEIGHT - player1.height;

      if (gameMode === "2p") {
        player2.y += player2.dy;
        if (player2.y < 0) player2.y = 0;
        if (player2.y > HEIGHT - player2.height) player2.y = HEIGHT - player2.height;
      } else {
        let aiSpeed = 3.2;
        let errorMargin = 25;

        if (difficulty === "easy") {
          aiSpeed = 2.5;
          errorMargin = 45;
        } else if (difficulty === "medium") {
          aiSpeed = 4.0;
          errorMargin = 20;
        } else if (difficulty === "hard") {
          aiSpeed = 5.8;
          errorMargin = 8;
        } else if (difficulty === "impossible") {
          aiSpeed = 8.5;
          errorMargin = 0;
        }

        let aiTarget = ball.y - player2.height / 2;
