            player2.y += aiSpeed;
          } else if (player2.y > aiTarget + (Math.random() - 0.5) * errorMargin) {
            player2.y -= aiSpeed;
          }
        }
        if (player2.y < 0) player2.y = 0;
        if (player2.y > HEIGHT - player2.height) player2.y = HEIGHT - player2.height;
