      ball.x += ball.vx;
      ball.y += ball.vy;

      if (ball.y <= 0) {
        ball.y = 0;
        ball.vy *= -1;
      } else if (ball.y >= HEIGHT - ballSize) {
        ball.y = HEIGHT - ballSize;
        ball.vy *= -1;
      }

